package org.telegram.othergram.theme;

import static org.telegram.messenger.LocaleController.getString;

import org.telegram.messenger.R;

/**
 * Built-in OtherGram themes. Their colors live in assets/og_vanilla_beige*.attheme,
 * generated by Tools/othergram/generate-themes.ps1; Theme.java registers them by these names.
 */
public class OtherGramThemes {

    // Theme names are persisted in preferences as theme keys, never rename them
    public static final String VANILLA_BEIGE = "OG Vanilla Beige";
    public static final String VANILLA_BEIGE_DARK = "OG Vanilla Beige Dark";

    public static final String VANILLA_BEIGE_ASSET = "og_vanilla_beige.attheme";
    public static final String VANILLA_BEIGE_DARK_ASSET = "og_vanilla_beige_dark.attheme";

    public static boolean isBuiltIn(String name) {
        return VANILLA_BEIGE.equals(name) || VANILLA_BEIGE_DARK.equals(name);
    }

    public static boolean isDark(String name) {
        return VANILLA_BEIGE_DARK.equals(name);
    }

    /** Localized name for a built-in OtherGram theme, or null for any other theme. */
    public static String getDisplayName(String name) {
        if (VANILLA_BEIGE.equals(name)) {
            return getString(R.string.OG_ThemeVanillaBeige);
        } else if (VANILLA_BEIGE_DARK.equals(name)) {
            return getString(R.string.OG_ThemeVanillaBeigeDark);
        }
        return null;
    }
}
